const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal'),mc=$('#modal-content');
const img=(id,cls='',alt='')=>`<img class="${cls}" src="assets/01_${id}.png" alt="${alt||names[id]||id}" ${cls.includes('fan')?'':'loading="lazy"'}>`;
const names={bang:'뱅!',mancato:'빗나감!',birra:'맥주',sceriffo:'보안관',vice:'부관',fuorilegge:'무법자',rinnegato:'배신자',barile:'술통',dinamite:'다이너마이트',prigione:'감옥',mustang:'야생마',mirino:'조준경',catbalou:'캣 벌로우',duello:'결투',gatling:'기관총',emporio:'잡화점',indiani:'인디언!',panico:'강탈!',saloon:'주점',diligenza:'역마차',wellsfargo:'웰스 파고 은행',volcanic:'볼캐닉',schofield:'스코필드',remington:'레밍턴',carabine:'리볼버 카빈',winchester:'윈체스터'};
const cards=[];
function add(id,en,type,short,text,note=''){cards.push({id,name:names[id]||en,en,type,short,text,note})}
add('bang','BANG!','기본 카드','상대 1명 공격','내 무기 사거리 안의 한 사람을 고릅니다. 상대가 빗나감!으로 막지 않으면 생명 1을 잃습니다. 사용한 카드는 버립니다.','<strong>내 차례에 보통 1장만 사용할 수 있어요.</strong> 볼캐닉이나 윌리 더 키드는 예외입니다.');
add('mancato','Missed!','기본 카드','총격 1회 피하기','뱅!이나 기관총으로 공격받을 때 손에서 내서 공격 1회를 막습니다. 내 차례가 아니어도 사용할 수 있습니다.','<strong>인디언!과 결투에는 빗나감!을 낼 수 없어요.</strong> <strong>슬랩 더 킬러의 뱅!은 빗나감! 효과 2개가 필요해요.</strong>');
add('birra','Beer','기본 카드','내 생명 +1','내 차례에 사용해서 생명 1을 회복합니다. 최대 생명을 넘길 수 없고, 남을 치료할 수 없습니다. 마지막 생명을 잃는 순간에는 내 차례가 아니어도 즉시 사용해 살아남을 수 있습니다.','<strong>생존자가 2명뿐이면 맥주는 효과가 없어요.</strong> 여러 피해로 생명이 0 이하가 되면 1 이상이 될 만큼 맥주가 필요해요.');
add('barile','Barrel','장비','♥(하트)를 공개하면 피하기','내 앞에 놓습니다. 뱅! 또는 기관총 공격마다 뽑는 더미 맨 위 1장을 공개해 즉시 버립니다. ♥(하트)면 빗나감! 1회 효과입니다. 실패해도 손의 빗나감!을 낼 수 있습니다.','공격 1회당 술통 판정은 한 번. 인디언!과 결투에는 사용할 수 없어요.');
add('prigione','Jail','장비','상대가 한 차례 쉬게 해요','거리와 관계없이 보안관 이외의 다른 사람 앞에 놓습니다. 그 사람의 차례 시작에 뽑는 더미 위 1장을 공개해 버립니다. ♥(하트)면 정상 진행, 아니면 이번 차례를 통째로 쉽니다. 감옥은 결과와 관계없이 버립니다.','감옥에 있어도 남의 차례에 빗나감!이나 위급한 맥주로 대응할 수 있어요.');
add('dinamite','Dynamite','장비','♠(스페이드) 2–9면 생명 −3','먼저 내 앞에 놓습니다. 다음 내 차례가 시작되면 뽑는 더미 위 1장을 공개해 버립니다. ♠(스페이드) 2~9면 폭발해 생명 3을 잃고 다이너마이트를 버립니다. 아니면 왼쪽 사람 앞으로 넘깁니다.','감옥도 있다면 다이너마이트부터 판정해요. 폭발은 어느 플레이어가 탈락시킨 것으로도 보지 않아요.');
add('mustang','Mustang','장비','상대가 나를 1칸 멀게 봐요','내 앞에 놓습니다. 다른 사람이 나까지 거리를 셀 때 +1 합니다. 내가 남을 보는 거리는 변하지 않습니다.');
add('mirino','Scope','장비','내가 상대를 1칸 가깝게 봐요','내 앞에 놓습니다. 내가 다른 사람까지 거리를 셀 때 1 줄입니다. 예를 들어 원래 거리 2인 상대를 거리 1로 보므로, 기본 총으로도 공격할 수 있습니다. 거리는 최소 1이며 다른 사람이 나를 보는 거리는 그대로입니다.');
add('panico','Panic!','행동','거리 1 · 카드 1장 뺏기','거리 1 이내 상대의 손에서 보지 않고 고른 1장, 또는 앞에 놓인 카드 중 원하는 1장을 가져와 내 손에 넣습니다.','야생마·조준경·캐릭터 능력은 거리를 바꿔요. 무기 사거리가 길어져도 강탈!의 범위는 늘지 않아요.');
add('catbalou','Cat Balou','행동','상대 카드 1장 버리기','거리와 관계없이 한 사람을 고릅니다. 상대 손에서 보지 않고 고른 1장, 또는 앞에 놓인 원하는 1장을 버립니다.');
add('duello','Duel','행동','뱅!으로 번갈아 대응','거리와 관계없이 한 명을 지목합니다. 상대부터 손의 뱅! 1장을 버리고, 이어서 나와 상대가 번갈아 뱅!을 버립니다. 먼저 버리지 못하거나 포기한 사람이 생명 1을 잃습니다.','<strong>빗나감!·술통은 사용할 수 없어요.</strong> 결투 중 버린 뱅!은 내 차례 뱅! 1장 제한에 포함되지 않아요.');
add('indiani','Indians!','행동','나 빼고 모두 뱅!을 버려요','나를 제외한 모든 사람이 뱅! 1장을 버리거나 생명 1을 잃습니다. 거리는 관계없습니다.','<strong>빗나감!이나 술통으로는 막을 수 없어요.</strong>');
add('gatling','Gatling','행동','다른 모두에게 총격','나를 제외한 모든 사람이 빗나감!으로 막거나 생명 1을 잃습니다. 거리는 관계없고 술통도 사용할 수 있습니다.','뱅! 카드가 아니므로 내 차례의 뱅! 1장 제한과 별개예요.');
add('saloon','Saloon','행동','생존자 모두 생명 +1','나를 포함한 모든 생존자가 생명 1을 회복합니다. 각자의 최대 생명까지만 회복합니다.','내 차례에만 사용해요. 마지막 생명을 잃는 순간에는 주점으로 구조할 수 없어요. 생존자 2명일 때도 효과가 있어요.');
add('emporio','General Store','행동','펼친 카드 1장씩 선택','현재 생존자 수만큼 뽑는 더미 위의 카드를 공개합니다. 나부터 시계 방향으로 각자 1장씩 골라 손에 넣습니다.');
add('diligenza','Stagecoach','행동','카드 2장 추가','뽑는 더미 위에서 카드 2장을 손에 넣습니다. 차례 시작에 뽑는 카드와 별개입니다.');
add('wellsfargo','Wells Fargo','행동','카드 3장 추가','뽑는 더미 위에서 카드 3장을 손에 넣습니다. 차례 시작에 뽑는 카드와 별개입니다.');
[['volcanic','Volcanic',1],['schofield','Schofield',2],['remington','Remington',3],['carabine','Rev. Carabine',4],['winchester','Winchester',5]].forEach(([id,en,r])=>add(id,en,'무기',`사거리 ${r}${r===1?' · 뱅! 여러 장 가능':''}`,`무기를 내 앞 판에 장착하세요. 총의 최대 사거리가 ${r}이 됩니다. 기존 무기가 있다면 버리고 교체합니다. 무기가 없어도 기본 콜트 .45로 거리 1을 공격할 수 있습니다.`,r===1?'손에 뱅!이 있는 만큼 쏠 수 있어요. 사거리는 여전히 1입니다.':'총을 놓는 것만으로 공격하지 않아요. 공격하려면 뱅! 카드가 필요해요.'));
const chars=[
['bartcassidy','바트 캐시디','Bart Cassidy',4,'생명을 1 잃을 때마다 뽑는 더미에서 1장을 즉시 뽑습니다.'],
['blackjack','블랙 잭','Black Jack',4,'차례 시작에 뽑는 두 번째 카드를 공개합니다. ♥(하트) 또는 ♦(다이아몬드)면 뽑는 더미에서 1장을 더 뽑습니다.'],
['calamityjanet','칼라미티 자넷','Calamity Janet',4,'뱅!을 빗나감!으로, 빗나감!을 뱅!으로 사용할 수 있습니다. 빗나감!을 뱅!으로 사용한 경우도 차례당 뱅! 1장 제한에 포함됩니다.'],
['elgringo','엘 그링고','El Gringo',3,'다른 사람의 카드로 생명을 1 잃을 때마다 그 사람 손에서 보지 않고 고른 1장을 가져옵니다. 상대 손에 카드가 없으면 가져오지 못합니다. 다이너마이트에는 적용되지 않습니다.'],
['jessejones','제시 존스','Jesse Jones',4,'차례 시작에 가져올 두 장 중 첫 카드를 뽑는 더미 대신 다른 사람 손에서 보지 않고 한 장을 가져올 수 있습니다. 두 번째 카드는 뽑는 더미에서 뽑습니다.'],
['jourdonnais','주르도네','Jourdonnais',4,'항상 술통 능력이 있습니다. 뱅!이나 기관총으로 공격받을 때 판정해 ♥(하트)면 빗나감! 효과입니다. 실제 술통도 있으면 각각 한 번씩 판정할 수 있습니다.'],
['kitcarlson','키트 칼슨','Kit Carlson',4,'차례 시작에 뽑는 더미 위 3장을 보고 2장을 손에 넣습니다. 나머지 1장은 뽑는 더미 맨 위에 뒷면으로 돌려놓습니다.'],
['luckyduke','럭키 듀크','Lucky Duke',4,'술통·감옥·다이너마이트 등 판정할 때 2장을 공개하고 원하는 한 장을 판정 결과로 선택합니다. 공개한 두 장은 모두 버립니다.'],
['paulregret','폴 리그레트','Paul Regret',3,'다른 사람은 나까지 거리를 +1 해서 셉니다. 실제 야생마도 놓으면 합해서 +2가 됩니다.'],
['pedroramirez','페드로 라미레즈','Pedro Ramirez',4,'차례 시작에 가져올 두 장 중 첫 카드를 뽑는 더미 대신 버린 카드 더미 맨 위에서 가져올 수 있습니다. 두 번째는 뽑는 더미에서 뽑습니다.'],
['rosedoolan','로즈 둘란','Rose Doolan',4,'다른 사람까지 거리를 −1 해서 봅니다. 실제 조준경도 있으면 합해서 −2입니다. 거리는 최소 1입니다.'],
['sidketchum','시드 케첨','Sid Ketchum',4,'언제든 손의 카드 2장을 버려 생명 1을 회복할 수 있습니다. 반복 가능하며 위급할 때도 사용할 수 있습니다. 최대 생명은 넘지 못합니다. 생존자가 2명이어도 가능합니다.'],
['slab','슬랩 더 킬러','Slab the Killer',4,'내 뱅!을 막으려면 빗나감! 효과 2개가 필요합니다. 성공한 술통은 빗나감! 효과 1개로 셉니다. 기관총에는 적용되지 않습니다.'],
['suzylafayette','수지 라파예트','Suzy Lafayette',4,'손에 카드가 한 장도 없게 되면 뽑는 더미에서 즉시 1장을 뽑습니다.'],
['vulturesam','벌처 샘','Vulture Sam',4,'누군가 탈락하면 그 사람의 손과 앞에 놓인 카드를 모두 가져와 내 손에 넣습니다.'],
['willythekid','윌리 더 키드','Willy the Kid',4,'내 차례에 뱅!을 여러 장 사용할 수 있습니다. 공격할 때마다 무기 사거리는 지켜야 합니다.']];
chars.forEach(([id,ko,en,hp,t])=>{names[id]=ko;add(id,en,'캐릭터',`기본 생명 ${hp}`,t,'캐릭터 능력이 기본 규칙과 다르면 능력을 우선합니다. 보안관은 최대·시작 생명이 1 늘어나요.')});
const roles=[['sceriffo','Sheriff','보안관','무법자와 배신자를 모두 탈락시키세요.','보안관만 역할 공개 · 생명 1 추가'],['vice','Deputy','부관','보안관을 지켜 같은 팀으로 승리하세요.','<strong>정체는 비밀</strong>'],['fuorilegge','Outlaw','무법자','보안관이 탈락하면 승리해요.','<strong>정체는 비밀</strong>'],['rinnegato','Renegade','배신자','모두를 없애고 마지막 혼자 살아남으세요.','다른 사람을 먼저 없애고, 보안관을 마지막에 탈락시키세요.']];
roles.forEach(([id,en,ko,t,n])=>add(id,en,'역할',t,t,n));
const counts={4:[1,0,2,1],5:[1,1,2,1],6:[1,1,3,1],7:[1,2,3,1]};
let saved={};try{saved=JSON.parse(localStorage.getItem('bang-first')||'{}')}catch{}let players=[4,5,6,7].includes(saved.players)?saved.players:4,step=0,done=Array.isArray(saved.done)?saved.done:[],phase=0,filter='전체',query='',attackState=0;
function persist(){try{localStorage.setItem('bang-first',JSON.stringify({players,done}))}catch{}}
function openModal(html){modal.querySelector(".hh-modal-footer")?.remove();modal.classList.remove("hh-selecting");mc.innerHTML=html;mc.scrollTop=0;if(!modal.open)modal.showModal()}
$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function cardDetail(id){const c=cards.find(x=>x.id===id);if(!c)return;openModal(`<div class="detail">${img(c.id,'',c.name+' 카드')}<div><span class="tag">${['기본 카드','행동'].includes(c.type)?'갈색 · 쓰고 버리기':c.type==='무기'?'파란색 · 무기 1개':c.type==='장비'?'파란색 · 앞에 놓기':c.type}</span><h2>${c.name}</h2><p class="en">${c.en}</p><p>${c.text}</p></div>${c.note?`<div class="callout">${c.note}</div>`:''}${(c.type==='무기'||['bang','panico'].includes(c.id))?'<p class="term-note">거리는 앉은 자리를 짧은 방향으로 세요. 옆 사람은 1, 한 명 건너면 2예요. 야생마·조준경·캐릭터 능력으로 달라질 수 있어요.</p>':''}${(/판정/.test(c.text)||['barile','prigione','dinamite'].includes(c.id))?'<p class="term-note">판정은 보통 뽑는 더미 맨 위 1장을 공개해 왼쪽 아래 무늬와 숫자를 확인하는 것이에요. 공개한 카드는 효과를 쓰지 않고 버려요. 캐릭터가 다른 판정 방법을 정하면 그 설명을 따라요.</p>':''}</div>`)}
function head(n,t,p){return `<div class="page-head"><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div>`}
function helps(){return `<div class="help-grid"><button class="help-btn" data-help="attack"><span>공격받았어요</span><b>→</b></button><button class="help-btn" data-help="distance"><span>거리 계산</span><b>→</b></button><button class="help-btn" data-help="dying"><span>생명이 0이에요</span><b>→</b></button><button class="help-btn" data-help="start"><span>감옥 · 폭탄</span><b>→</b></button><button class="help-btn" data-help="win"><span>누가 이기나요?</span><b>→</b></button></div>`}
function seatMap(n,selected=null,interactive=false){
 const point=(r,angle)=>{const a=angle*Math.PI/180;return [180+r*Math.cos(a),180+r*Math.sin(a)]};
 const max=Math.floor(n/2);let arcs='';
 for(let d=max;d>=1;d--){const r=99+d*19;for(const side of [1,-1]){const angle=90-side*d*360/n;const start=point(r,90),end=point(r,angle),label=point(r+9,90-side*d*180/n);arcs+=`<path d="M ${start.join(' ')} A ${r} ${r} 0 0 ${side===1?0:1} ${end.join(' ')}" fill="none" stroke="#b1b5ad" stroke-width="1.2" stroke-dasharray="3 5" marker-end="url(#${interactive?'calc':'intro'}-arrow)"/><text x="${label[0]}" y="${label[1]}" class="route-number" text-anchor="middle" dominant-baseline="middle">${d}</text>`}}
 return `<div class="seats distance-map schematic-map" role="${interactive?'group':'img'}" aria-label="${n}명 원형 테이블. 나에서 양쪽으로 자리 간격을 세어 가까운 쪽의 거리를 사용해요."><svg class="distance-routes" viewBox="0 0 360 360" aria-hidden="true"><defs><marker id="${interactive?'calc':'intro'}-arrow" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M 0 0 L 8 4 L 0 8 Z" fill="#353a32"/></marker></defs><circle cx="180" cy="180" r="75" fill="#e5e7df" stroke="#949b8f" stroke-width="1.2"/>${arcs}</svg>${Array.from({length:n},(_,i)=>{const angle=Math.PI/2-i*2*Math.PI/n;const tag=interactive?'button':'div';return `<${tag} class="seat ${i===0?'me':i===selected?'selected':''}" style="left:${50+26.67*Math.cos(angle)}%;top:${50+26.67*Math.sin(angle)}%" ${interactive?`data-target="${i}" aria-label="${i===0?'내 자리':i+'번 상대 선택'}"`:''}><span>${String.fromCharCode(65+i)}</span>${i===0?'<small>나</small>':''}</${tag}>`}).join('')}</div>`}
function home(){main.innerHTML=`<div class="home-top"><h1>뱅! 첫 게임</h1><span>기본판 · 4–7명</span></div><section class="start-card"><div class="start-top"><span>게임 준비</span><span>5단계</span></div><h2>카드를 꺼내고<br>시작하세요.</h2><p>카드로 공격하고, 내 생명을 지키세요.<br>역할마다 이기는 조건이 달라요.</p><div class="start-art">${img('sceriffo')}${img('bang')}${img('jessejones')}</div><a class="start-link" href="#setup"><span>처음부터 준비하기</span><b>→</b></a></section><div class="home-tools"><a class="tool-card cream" href="#turn"><span>게임 진행 <b>→</b></span><ol class="turn-preview"><li>2장 뽑기</li><li>카드 쓰기</li><li>초과 카드 버리기</li></ol><small>순서대로 따라 하기</small></a><a class="tool-card mint" href="#cards"><span>카드 찾기 <b>→</b></span><div class="mini-cards">${img('mancato')}${img('birra')}</div><small>그림으로 사용법 확인</small></a></div><section class="help-section"><h2>막혔을 때</h2>${helps()}</section>`}

const stepNames=['인원·역할','역할 배분','캐릭터','카드 배분','준비 끝'];
function setup(){main.innerHTML=head('','게임 준비','')+`<div class="layout"><aside class="steps">${stepNames.map((n,i)=>`<button class="step ${step===i?'on':''} ${done.includes(i)?'done':''}" data-step="${i}"><span class="n">${done.includes(i)?'✓':i+1}</span>${n}</button>`).join('')}<div class="progress"><i style="width:${done.length/5*100}%"></i></div></aside><section class="panel" aria-live="polite">${setupPanel()}<div class="panel-actions"><button class="btn text" id="prev-step" ${step===0?'disabled':''}>← 이전</button>${step<4?'<button class="btn" id="next-step">다음 →</button>':'<a class="btn" id="finish-setup" href="#turn">첫 차례 시작 →</a>'}</div></section></div>`;$('#prev-step').onclick=()=>{step--;setup();window.scrollTo({top:0,behavior:'instant'})};if($('#next-step'))$('#next-step').onclick=()=>{if(!done.includes(step))done.push(step);persist();step++;setup();window.scrollTo({top:0,behavior:'instant'})};if($('#finish-setup'))$('#finish-setup').onclick=()=>{if(!done.includes(4))done.push(4);persist()};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;setup();window.scrollTo({top:0,behavior:'instant'})});document.querySelectorAll('[data-players]').forEach(b=>b.onclick=()=>{players=+b.dataset.players;done=[];persist();setup()})}
function tokens(n){return `<div class="token-row" role="img" aria-label="총알 토큰 ${n}개, 생명 ${n}">${Array.from({length:n},()=>'<img src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2270%22%20height%3D%22130%22%20viewBox%3D%220%200%2070%20130%22%3E%3Cdefs%3E%3ClinearGradient%20id%3D%22g%22%3E%3Cstop%20stop-color%3D%22%23ab7526%22%2F%3E%3Cstop%20offset%3D%22.25%22%20stop-color%3D%22%23f3d384%22%2F%3E%3Cstop%20offset%3D%22.6%22%20stop-color%3D%22%23d9ad53%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%23aa7224%22%2F%3E%3C%2FlinearGradient%3E%3ClinearGradient%20id%3D%22tip%22%20x2%3D%220%22%20y2%3D%221%22%3E%3Cstop%20stop-color%3D%22%23d4a46b%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%2394643b%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%3Cpath%20d%3D%22M16%20119V42C16%2020%2026%207%2035%203c9%204%2019%2017%2019%2039v77z%22%20fill%3D%22%23785e3b%22%20opacity%3D%22.16%22%20transform%3D%22translate(1%203)%22%2F%3E%3Cpath%20d%3D%22M17%2046C17%2024%2026%209%2035%205c9%204%2018%2019%2018%2041%22%20fill%3D%22url(%23tip)%22%20stroke%3D%22%2373502d%22%20stroke-width%3D%222%22%2F%3E%3Cpath%20d%3D%22M16%2044h38v72H16z%22%20fill%3D%22url(%23g)%22%20stroke%3D%22%238d652c%22%20stroke-width%3D%222%22%2F%3E%3Cpath%20d%3D%22M14%20111h42v11H14z%22%20rx%3D%223%22%20fill%3D%22url(%23g)%22%20stroke%3D%22%238d652c%22%20stroke-width%3D%222%22%2F%3E%3Cpath%20d%3D%22M24%2051v51%22%20stroke%3D%22%23fff0ba%22%20stroke-width%3D%223%22%20opacity%3D%22.7%22%2F%3E%3Cpath%20d%3D%22M17%2049h36M17%20106h36%22%20stroke%3D%22%239f732d%22%20stroke-width%3D%221%22%2F%3E%3C%2Fsvg%3E%0A" alt="">').join('')}</div>`}
function setupPanel(){
if(step===0)return `<span class="number">준비 1 / 5</span><h2 class="setup-step-heading"><span class="setup-task-number">1</span><span>개인판부터 나눠주세요.</span></h2><p class="lead">기본판은 4–7명.</p><div class="board-intro"><img src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22600%22%20height%3D%22320%22%20viewBox%3D%220%200%20600%20320%22%3E%3Crect%20x%3D%224%22%20y%3D%224%22%20width%3D%22592%22%20height%3D%22312%22%20rx%3D%2224%22%20fill%3D%22%23d7b984%22%20stroke%3D%22%23ad8954%22%20stroke-width%3D%223%22%2F%3E%3Crect%20x%3D%2216%22%20y%3D%2216%22%20width%3D%22568%22%20height%3D%22288%22%20rx%3D%2217%22%20fill%3D%22%23e8d4b0%22%20stroke%3D%22%23c1a16c%22%2F%3E%3Cg%20fill%3D%22%23b48636%22%20stroke%3D%22%23816126%22%20stroke-width%3D%221.5%22%3E%3Cpath%20id%3D%22b%22%20d%3D%22M190%2060V46c0-11%205-19%2010-22%205%203%2010%2011%2010%2022v14h2v9h-24v-9z%22%2F%3E%3Cuse%20href%3D%22%23b%22%20transform%3D%22translate(50%200)%22%2F%3E%3Cuse%20href%3D%22%23b%22%20transform%3D%22translate(100%200)%22%2F%3E%3Cuse%20href%3D%22%23b%22%20transform%3D%22translate(150%200)%22%2F%3E%3Cuse%20href%3D%22%23b%22%20transform%3D%22translate(200%200)%22%2F%3E%3C%2Fg%3E%3Cg%20fill%3D%22%23f4e8d1%22%20stroke%3D%22%23b5996d%22%20stroke-width%3D%222%22%3E%3Crect%20x%3D%2264%22%20y%3D%2291%22%20width%3D%22136%22%20height%3D%22174%22%20rx%3D%229%22%2F%3E%3Crect%20x%3D%22232%22%20y%3D%2291%22%20width%3D%22136%22%20height%3D%22174%22%20rx%3D%229%22%2F%3E%3Crect%20x%3D%22400%22%20y%3D%2291%22%20width%3D%22136%22%20height%3D%22174%22%20rx%3D%229%22%2F%3E%3C%2Fg%3E%3Cg%20fill%3D%22%23795f3d%22%20font-family%3D%22sans-serif%22%20text-anchor%3D%22middle%22%20font-size%3D%2219%22%3E%3Ctext%20x%3D%22132%22%20y%3D%22187%22%3E%EC%97%AD%ED%95%A0%3C%2Ftext%3E%3Ctext%20x%3D%22300%22%20y%3D%22187%22%3E%EC%BA%90%EB%A6%AD%ED%84%B0%3C%2Ftext%3E%3Ctext%20x%3D%22468%22%20y%3D%22187%22%3E%EB%AC%B4%EA%B8%B0%3C%2Ftext%3E%3C%2Fg%3E%3Ctext%20x%3D%22300%22%20y%3D%22292%22%20font-family%3D%22sans-serif%22%20font-size%3D%2214%22%20text-anchor%3D%22middle%22%20fill%3D%22%238a7250%22%3E%EA%B0%9C%EC%9D%B8%ED%8C%90%20%C2%B7%20%EC%83%81%EB%8B%A8%EC%97%90%20%EC%83%9D%EB%AA%85%20%ED%91%9C%EC%8B%9C%3C%2Ftext%3E%3C%2Fsvg%3E" alt="역할·캐릭터·무기·총알을 놓는 개인판 배치 예시"><h3>각자 개인판 1장</h3><p>한 장씩 받아 자기 앞에 놓으세요.<br>총알 토큰은 우선 테이블 중앙에 모아두세요.</p><p>설명 요약 카드도 1장씩 받아 옆에 두세요.</p><div class="component-token"><img src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2270%22%20height%3D%22130%22%20viewBox%3D%220%200%2070%20130%22%3E%3Cdefs%3E%3ClinearGradient%20id%3D%22g%22%3E%3Cstop%20stop-color%3D%22%23ab7526%22%2F%3E%3Cstop%20offset%3D%22.25%22%20stop-color%3D%22%23f3d384%22%2F%3E%3Cstop%20offset%3D%22.6%22%20stop-color%3D%22%23d9ad53%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%23aa7224%22%2F%3E%3C%2FlinearGradient%3E%3ClinearGradient%20id%3D%22tip%22%20x2%3D%220%22%20y2%3D%221%22%3E%3Cstop%20stop-color%3D%22%23d4a46b%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%2394643b%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%3Cpath%20d%3D%22M16%20119V42C16%2020%2026%207%2035%203c9%204%2019%2017%2019%2039v77z%22%20fill%3D%22%23785e3b%22%20opacity%3D%22.16%22%20transform%3D%22translate(1%203)%22%2F%3E%3Cpath%20d%3D%22M17%2046C17%2024%2026%209%2035%205c9%204%2018%2019%2018%2041%22%20fill%3D%22url(%23tip)%22%20stroke%3D%22%2373502d%22%20stroke-width%3D%222%22%2F%3E%3Cpath%20d%3D%22M16%2044h38v72H16z%22%20fill%3D%22url(%23g)%22%20stroke%3D%22%238d652c%22%20stroke-width%3D%222%22%2F%3E%3Cpath%20d%3D%22M14%20111h42v11H14z%22%20rx%3D%223%22%20fill%3D%22url(%23g)%22%20stroke%3D%22%238d652c%22%20stroke-width%3D%222%22%2F%3E%3Cpath%20d%3D%22M24%2051v51%22%20stroke%3D%22%23fff0ba%22%20stroke-width%3D%223%22%20opacity%3D%22.7%22%2F%3E%3Cpath%20d%3D%22M17%2049h36M17%20106h36%22%20stroke%3D%22%239f732d%22%20stroke-width%3D%221%22%2F%3E%3C%2Fsvg%3E%0A" alt="총알 토큰 모양 예시"><span>총알 토큰<br><b>1개 = 생명 1</b></span></div></div><section class="card-kinds sort-cards" aria-labelledby="sort-cards-title"><h2 id="sort-cards-title" class="setup-step-heading"><span class="setup-task-number">2</span><span>카드를 3개 더미로 나누세요.</span></h2><p class="sort-instruction"><strong>카드 뒷면 디자인을 보고, 같은 그림끼리 모으세요.</strong><br>역할·캐릭터·플레이 카드는 뒷면으로 구분할 수 있어요.</p><p>각 더미에서 1장씩 앞면을 확인하면 더 쉬워요.</p><div class="kind-grid"><figure>${img('sceriffo')}<b>역할 카드 · 7장</b><small>보안관·부관·무법자·배신자<br>내가 이기는 목표</small></figure><figure>${img('jessejones')}<b>캐릭터 카드 · 16장</b><small>인물 이름·생명·특수 능력<br>각자 맡을 인물</small></figure><figure>${img('bang')}<b>플레이 카드 · 80장</b><small>뱅!·맥주·무기 등<br>갈색·파란 테두리를 함께 모아요</small></figure></div><div class="sort-check"><strong>역할 / 캐릭터 / 플레이</strong><span>3개 더미가 준비됐나요? 서로 섞지 말고 따로 두세요.<br>설명 요약 카드는 옆에 두세요.</span></div></section><h2 class="setup-step-heading setup-task-divider"><span class="setup-task-number">3</span><span>인원에 맞춰 역할을 골라요.</span></h2><div class="people" aria-label="플레이어 수">${[4,5,6,7].map(n=>`<button data-players="${n}" aria-pressed="${players===n}" class="${players===n?'on':''}">${n}명</button>`).join('')}</div><div class="role-list">${roles.map(([id,en,n,t],i)=>`<div class="role-item ${counts[players][i]===0?'unused':''}">${img(id)}<h3>${n} <span class="count">× ${counts[players][i]}</span></h3><p>${counts[players][i]===0?'사용하지 않아요':t}</p></div>`).join('')}</div><div class="callout">위 역할 카드 <b>총 ${players}장</b>만 골라요. 남은 역할 카드는 상자에 넣으세요.</div>`;
if(step===1)return `<span class="number">준비 2 / 5</span><h2>역할을 한 장씩 나누세요.</h2><p class="lead">고른 역할 카드 ${players}장을 섞어 1장씩 나눠요. 그림이 안 보이는 뒷면으로 주고, <strong>각자 몰래 확인하세요.</strong></p><div class="visual-row"><figure><div class="card-back">BANG!</div><figcaption>각자 역할 1장</figcaption></figure><span class="symbol">→</span><figure>${img('sceriffo')}<figcaption>보안관만 앞면으로 놓기</figcaption></figure></div><div class="callout"><strong>다른 역할은 비밀.</strong> 역할 카드는 플레이 카드와 섞지 말고 따로 두세요. 생명이 0이 되어 회복하지 못하면 탈락해요.</div><div class="goal-rows">${roles.map(([id,en,n,t])=>`<div><b>${n}</b><span>${t}</span></div>`).join('')}</div><button class="btn text" data-help="win">승리 조건 자세히 →</button>`;
if(step===2)return `<span class="number">준비 3 / 5</span><h2>캐릭터를 받고 생명을 표시하세요.</h2><p class="lead">캐릭터를 섞어 각자 1장씩 공개해요.<br>이름과 능력을 모두에게 읽어주세요.<br><strong>시작 전에 서로의 캐릭터와 능력을 확인하세요.</strong> 캐릭터 카드는 모두가 볼 수 있게 앞면으로 두세요.</p><div class="life-demo">${img('jessejones')}<div><span>캐릭터의 총알 수</span><strong>4</strong><span>시작 생명 · 최대 생명</span></div></div><div class="token-example">${tokens(4)}<p>총알 토큰 4개 = 생명 4</p></div><div class="callout"><b>보안관은 생명 +1.</b><br>기본 생명 4라면 보안관은 5로 시작해요.</div><p>캐릭터의 총알 그림 수만큼 총알 토큰을 개인판 상단에 놓으세요. 이 수가 시작 생명이자 회복 가능한 최대 생명이에요. 생명 1을 잃으면 토큰 1개를 치우고, 회복하면 다시 가져와요.</p><details><summary>총알 토큰이 없는 판본이라면</summary><p>남은 캐릭터 카드 한 장을 뒷면으로 놓으세요. 그 위에 내 캐릭터 카드를 겹쳐 총알 그림을 가리거나 드러내며 생명을 표시해요.</p></details><a class="btn secondary" href="#cards" data-category="캐릭터">내 캐릭터 능력 찾기 →</a>`;
if(step===3)return `<span class="number">준비 4 / 5</span><h2>생명 수만큼 카드를 받으세요.</h2><p class="lead">갈색·파란 테두리의 플레이 카드 80장을 함께 섞어요. 각자 시작 생명 수만큼 뒷면으로 받아 손에 들어요.</p><div class="deal-example"><div><strong>4</strong><span>시작 생명</span></div><b>→</b><div><strong>4장</strong><span>처음 손의 카드</span></div></div><p>보안관도 늘어난 생명 수만큼 받아요.<br><strong>손의 카드는 다른 사람에게 보이지 않게 해요.</strong></p><div class="tableau"><div class="draws"><figure><div class="card-back">BANG!</div><figcaption>남은 카드 · 뒷면</figcaption></figure><figure><div class="discard-slot"></div><figcaption>버리는 자리 · 비워두기</figcaption></figure></div><span class="table-caption">테이블 중앙 ↑ &nbsp; 내 앞 ↓</span><div class="mine"><figure>${img('sceriffo')}<figcaption>역할</figcaption></figure><figure>${img('jessejones')}<figcaption>캐릭터</figcaption></figure><div class="life-tokens">${tokens(5)}<small>생명 · 예: 보안관 5</small></div></div></div><p class="library-note">역할 그림은 보안관의 예시예요. <strong>다른 역할은 뒷면으로 두세요.</strong> 개인판이 있으면 표시 자리에 놓아요.</p><div class="callout"><strong>파란 테두리 장비도 처음에는 손에 들고, 내 차례에 내려놓아요.</strong></div>`;
return `<span class="number">준비 5 / 5</span><h2>보안관부터 시작하세요.</h2><div class="ready-number">↻</div><p class="lead">보안관부터 시작해요.<br>끝나면 왼쪽 사람에게 차례를 넘겨요.</p><div class="check-list"><div>개인판 1장 <span>내 앞에 놓기</span></div><div>역할 1장 <span>보안관만 공개</span></div><div>캐릭터 1장 <span>모두 공개</span></div><div>총알 토큰 <span>보안관은 1개 더</span></div><div>손에 카드 <span>시작 생명 수만큼</span></div><div>뽑는 카드 더미 <span>옆에 버리는 자리</span></div></div><div class="callout">첫 차례도 <b>카드 2장 뽑기 → 카드 쓰기 → 초과 카드 버리기.</b><br>아래 버튼을 누르고 한 단계씩 진행하세요.</div>`}

function turn(){const data=[['뽑는 더미에서 2장을 가져오세요.','중앙에 뒷면으로 쌓인 카드가 뽑는 더미예요. 맨 위 2장을 가져와 손에 든 카드에 더하세요. 캐릭터의 뽑기 능력이 있으면 그 설명을 따라요.','<div class="card-back">BANG!</div><span class="symbol">→</span><div class="draw-amount"><strong>2장</strong><span>내 손에 추가</span></div>'],['원하는 카드를 쓰세요.','공격하거나, 회복하거나, 장비를 놓아요. 원하는 만큼 카드를 전부 사용하면 돼요. 다만 <strong>뱅! 카드는 보통 내 차례에 1장만 쓸 수 있어요.</strong> 한 장도 쓰지 않고 넘어가도 괜찮아요.','<figure class="turn-card-label">'+img('bang')+'<figcaption>뱅! 카드</figcaption></figure><figure class="turn-card-label">'+img('birra')+'<figcaption>갈색 카드</figcaption></figure><figure class="turn-card-label">'+img('barile')+'<figcaption>파란 카드</figcaption></figure>'],['손에 남길 카드 수를 맞추세요.','현재 생명이 3이면 손에 최대 3장만 남겨요. 5장을 들고 있다면 원하는 2장을 중앙의 버리는 자리에 앞면으로 놓으세요. <strong>손의 카드가 생명 이하라면 버리지 않아요.</strong> <strong>내 앞에 내려놓은 장비는 세지 않아요.</strong>','<div class="hand-example"><span>예: 현재 생명 3</span><strong>손에 최대 3장</strong><small>5장이면 2장을 골라 버리기</small></div>']][phase];main.innerHTML=head('','내 차례','한 사람이 아래 세 단계를 마치면 왼쪽 사람 차례예요.')+`${phase===0?'<div class="callout">내 앞에 다이너마이트나 감옥이 있나요? <b>카드를 뽑기 전에</b> 확인해요. 둘 다 있다면 다이너마이트부터. 없다면 바로 2장을 뽑으세요. <button class="btn text" data-help="start">처리 방법 보기 →</button></div>':''}<div class="turn-tabs" role="tablist" aria-label="차례 진행 순서">${['① 2장 뽑기','② 카드 쓰기','③ 초과 카드 버리기'].map((n,i)=>`<button role="tab" aria-selected="${phase===i}" class="${phase===i?'on':''}" data-phase="${i}">${n}</button>`).join('')}</div><section class="turn-content" role="tabpanel"><div><span class="number">내 차례 ${phase+1} / 3</span><h2>${data[0]}</h2><p>${data[1]}</p>${phase===1?`<aside class="distance-intro"><h3>공격하기 전, 거리부터 확인해요.</h3>${seatMap(6)}<p class="distance-caption">A가 나예요. 점선을 따라 세면<br>B·F는 거리 1, C·E는 거리 2, D는 거리 3.</p><ul><li>양쪽으로 세어 <strong>더 짧은 방향</strong>을 골라요. 탈락한 사람은 빼고 세요.</li><li><strong>기본 총은 거리 1까지</strong> 닿아요. 무기 카드의 조준점 안 숫자는 총이 닿는 최대 거리예요.</li></ul><p>야생마·조준경·캐릭터 능력이 있으면 거리가 달라질 수 있어요.</p><button class="btn text" data-help="distance">내 거리 계산하기 →</button></aside><div class="turn-visual">${data[2]}</div><div class="play-basics"><div><b class="brown-dot">갈색 테두리</b><span>효과를 적용하고, 버리는 자리에 앞면으로 놓아요.</span></div><div><b class="blue-dot">파란 테두리</b><span>손에서 골라 내 앞에 앞면으로 놓아요. 제거될 때까지 효과가 유지돼요. 감옥은 상대 앞에 놓아요.</span></div><div><b>제한</b><ul class="rule-lines"><li><strong>뱅!은 보통 내 차례에 1장만 써요.</strong></li><li><strong>내 앞 판에는 무기 1개만 장착해요. 같은 이름의 장비는 1장만 놓아요.</strong></li><li><strong>새 무기를 내 앞 판에 장착하면 이전 무기는 버려요.</strong></li><li><strong>카드·캐릭터에 예외 능력이 있으면 그 설명을 따라요.</strong></li></ul></div></div>`:''}${phase===1?`<div class="turn-actions turn-card-actions"><div class="turn-card-help"><small>뭘 내야 할지 모르겠다면?</small><a class="btn secondary" href="#hand">내 카드 활용</a></div><button class="btn" id="next-phase">다음 순서 보기 →</button></div>`:''}</div>${phase!==1?`<div class="turn-visual">${data[2]}</div>`:''}${phase===2?`<div class="turn-next turn-end"><button class="btn" id="next-phase">차례 종료 · 다음 사람에게 ↻</button></div>`:''}</section>${phase===0?'<p class="callout">게임 중 카드 효과와 기호는 <strong>설명 요약 카드</strong>를 참고하세요.</p><div class="turn-next turn-actions"><button class="btn" id="next-phase">다음 순서 보기 →</button></div>':''}`;document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=+b.dataset.phase;turn()});$('#next-phase').onclick=()=>{phase=(phase+1)%3;turn();window.scrollTo({top:0,behavior:'instant'})};document.querySelectorAll('[data-response]').forEach(b=>b.onclick=()=>{attackState=+b.dataset.response;$('#attack-result').textContent=attackState===1?'상대 생명은 그대로예요. 뱅!과 빗나감!을 모두 중앙에 버려요. 공격한 사람은 자기 차례를 계속해요.':'뱅!을 중앙에 버리고, 상대의 총알 토큰 1개를 치워 생명을 1 줄여요. 상대 생명이 0이면 즉시 맥주로 살 수 있는지 확인하세요. 공격한 사람은 자기 차례를 계속해요.'})}
function esc(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const normalize=s=>s.toLowerCase().replace(/[\s!·.]/g,'');
function matches(c,q){return normalize([c.name,c.en,c.short,c.text,c.note,c.type].join(' ')).includes(normalize(q))}
function tiles(){const filtered=cards.filter(c=>(filter==='전체'||c.type===filter||filter==='행동'&&c.type==='기본 카드')&&matches(c,query));return filtered.length?filtered.map(c=>`<button class="card-tile" data-card="${c.id}">${img(c.id)}<h3>${c.name}</h3><p>${c.short}</p></button>`).join(''):'<div class="empty">찾는 카드가 없어요. 다른 카드 이름이나 효과로 검색해 보세요.<br>예: 맥주, 총, 감옥, 생명</div>'}
function library(){main.innerHTML=head('','카드 찾기','그림을 누르면 사용법이 나와요.')+`<label for="card-search" class="library-note">이름·효과로 검색</label><input id="card-search" class="search-field" placeholder="예: 빗나감, 맥주, 감옥, 회복…" value="${esc(query)}"><div class="filters">${['전체','행동','장비','무기','역할','캐릭터'].map(f=>`<button class="chip ${filter===f?'on':''}" aria-pressed="${filter===f}" data-filter="${f}">${f}</button>`).join('')}</div><p class="library-note">이미지는 외국어 판본이에요. 실물 카드와 그림을 비교해 찾으세요.</p><div class="library-grid" id="card-grid">${tiles()}</div>`;$('#card-search').oninput=e=>{query=e.target.value;$('#card-grid').innerHTML=tiles()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;library()})}
const helpInfo={attack:['공격을 어떻게 막죠?',`<div class="attack"><div>${img('bang')}<p>뱅! / 기관총</p></div><span class="arrow">→</span><div>${img('mancato')}<p>빗나감!으로 막기</p></div></div><p>내 차례가 아니어도 즉시 빗나감!을 낼 수 있어요. 내 앞에 술통이 있다면 뽑는 더미 맨 위 1장을 공개해요. ♥(하트)면 공격을 막고, 아니면 손의 빗나감!을 낼 수 있어요. 공개한 카드는 버려요. 막지 못하면 생명 1을 잃습니다.</p><div class="callout"><b>인디언!과 결투는 뱅!으로 대응해요.</b><br>빗나감!이나 술통으로 막지 못해요. <strong>슬랩 더 킬러의 뱅!은 빗나감! 효과 2개가 필요해요.</strong></div><button class="btn secondary" data-help="dying">생명이 0이 됐다면 →</button>`],dying:['생명 0, 맥주가 있나요?',`<div class="visual-row">${img('birra')}<span class="symbol">+1 ♡</span></div><p>마지막 생명을 잃는 그 순간, 손의 맥주를 즉시 내서 생명을 1 이상으로 만들면 살아남아요. 다이너마이트 등으로 0 아래가 됐다면 여러 장이 필요할 수 있어요.</p><div class="callout">생존자가 <b>2명뿐이면 맥주는 효과가 없어요.</b> <strong>주점으로 대신 구조할 수도 없어요.</strong> 시드 케첨처럼 회복 능력이 있다면 그 능력을 확인하세요.</div><p>살아남지 못하면 역할을 공개하고 손과 앞의 카드를 모두 버려요. 벌처 샘이 있으면 그가 가져갑니다. 탈락자는 거리 계산에서 빠져요.</p><button class="btn secondary" data-help="win">탈락 보상과 승리 조건 →</button>`],start:['감옥·다이너마이트 처리',`<p>뽑는 더미 맨 위 1장을 뒤집어, 무늬와 숫자를 확인하세요.</p><div class="visual-row"><figure>${img('dinamite')}<figcaption>1. 다이너마이트</figcaption></figure><span class="symbol">→</span><figure>${img('prigione')}<figcaption>2. 감옥</figcaption></figure></div><p><b>내 앞에 다이너마이트가 있다면:</b> 내 차례 시작에 뽑는 더미 위 1장을 공개해 ♠(스페이드) 2–9면 폭발! 생명 3을 잃고 다이너마이트를 버려요. 아니면 다이너마이트를 왼쪽 사람에게 넘겨요.</p><p><b>내 앞에 감옥이 있다면:</b> 뽑는 더미 위 1장을 공개해 ♥(하트)면 평소처럼 2장을 뽑고 진행해요. 아니면 카드 뽑기·사용·정리를 모두 건너뛰고 왼쪽 사람에게 차례를 넘겨요. 감옥 카드는 어느 쪽이든 버려요.</p><div class="callout">무늬와 숫자를 확인하기 위해 뽑은 카드는 <b>효과를 쓰지 않고 즉시 버려요.</b> 손으로 가져오지 않아요. 판정이 끝났고 차례를 쉬지 않는다면 이제 2장을 뽑으세요.</div>`],win:['내 편은 언제 이기나요?',`<div class="role-list">${roles.map(([id,en,n,t,note])=>`<div class="role-item">${img(id)}<h3>${n}</h3><p>${t}</p></div>`).join('')}</div><div class="callout"><strong>보안관이 탈락하면 즉시 종료!</strong> 배신자만 홀로 살아 있다면 배신자 승리, 그 외엔 무법자 팀이 이겨요. 배신자는 보안관과 최후의 1대1을 만든 뒤 이겨야 해요.</div><p><b>탈락시킨 보상:</b> 무법자를 탈락시킨 누구든 3장을 뽑아요.<br><b>보안관의 벌칙:</b> 부관을 탈락시키면 손과 앞의 카드를 전부 버려요.<br>다이너마이트의 피해는 어느 플레이어가 탈락시킨 것으로도 보지 않아요.</p><p class="library-note">보안관·부관과 무법자는 이미 탈락했더라도 자신의 팀이 이기면 함께 승리해요.</p>`]};
function showHelp(id){if(id==='distance'){distPlayers=players;target=null;mustang=false;paul=false;distance();return}const h=helpInfo[id];if(h)openModal(`<h2 style="margin:15px 0">${h[0]}</h2>${h[1]}`)}
let distPlayers=players,target=1,weapon=1,scope=false,mustang=false,rose=false,paul=false;
const calcWeapons=[['colt','기본 총',1],['volcanic','볼캐닉',1],['schofield','스코필드',2],['remington','레밍턴',3],['carabine','리볼버 카빈',4],['winchester','윈체스터',5]];
let calcWeapon='colt';
function calculatorSeats(n,selected){return `<div class="seats calculator-seats"><div class="table-label">${selected===null?'자리를<br>눌러주세요':`${selected}<br><small>선택됨</small>`}</div>${Array.from({length:n},(_,i)=>{const a=Math.PI/2-i*2*Math.PI/n;return `<button class="seat ${i===0?'me':i===selected?'selected':''}" style="left:${50+39*Math.cos(a)}%;top:${50+38*Math.sin(a)}%" data-target="${i}" aria-label="${i===0?'내 자리':i+'번 자리 선택'}" ${i===0?'disabled':`aria-pressed="${i===selected}"`}><span>${i===0?'나':i}</span>${i===0?'':`<small>거리 ${Math.min(i,n-i)}</small>`}</button>`}).join('')}</div>`}
function distance(){
 if(target!==null&&target>=distPlayers)target=null;
 openModal(`<div class="calculator"><h2>저 사람에게 쏠 수 있나요?</h2><div class="calc-reminder"><strong>이 도구는 뱅!의 거리 조건을 확인해요.</strong><p>총이 닿아도 내 차례에 손의 뱅! 카드를 내야 공격해요. 보통 내 차례에 1장만 쓸 수 있어요. 볼캐닉·윌리 더 키드는 여러 장 쓸 수 있어요.</p></div><section class="calc-step"><h3><span>1</span> 공격할 자리를 고르세요</h3><label class="form-row">게임에 남은 사람 수<select id="dist-distPlayers">${[2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===distPlayers?'selected':''}>${n}명</option>`).join('')}</select></label><p class="calc-hint">‘나’를 기준으로 오른쪽부터 앉은 순서대로 고르세요. 탈락한 사람은 빼요.</p><div id="calc-seats">${calculatorSeats(distPlayers,target)}</div></section><section class="calc-step"><h3><span>2</span> 내 앞에 놓인 카드만 선택하세요</h3><label class="calc-label" for="weapon">내 무기</label><select class="calc-select" id="weapon">${calcWeapons.map(([id,name,r])=>`<option value="${id}" ${id===calcWeapon?'selected':''}>${name} · 사거리 ${r}</option>`).join('')}</select><p class="calc-hint">손에 들고 있는 무기는 적용하지 않아요.</p><label class="form-row">내 조준경이 있어요<input id="scope" type="checkbox" ${scope?'checked':''}></label><label class="form-row">내 캐릭터가 로즈 둘란이에요<input id="rose" type="checkbox" ${rose?'checked':''}></label></section><section class="calc-step"><h3><span>3</span> 상대의 카드를 확인하세요</h3><p class="calc-hint" id="target-hint"></p><label class="form-row">야생마가 있어요<input id="mustang" type="checkbox" ${mustang?'checked':''} ${target===null?'disabled':''}></label><label class="form-row">캐릭터가 폴 리그레트예요<input id="paul" type="checkbox" ${paul?'checked':''} ${target===null?'disabled':''}></label><p class="calc-hint">자리를 바꾸면 다시 확인해요.</p></section><div class="calc-answer" id="dist-result" role="status" aria-live="polite"></div></div>`);
 $('#calc-seats').onclick=e=>{const b=e.target.closest('[data-target]');if(!b||+b.dataset.target===0)return;const next=+b.dataset.target;if(target!==next){mustang=false;paul=false;$('#mustang').checked=false;$('#paul').checked=false}target=next;$('#calc-seats').innerHTML=calculatorSeats(distPlayers,target);$('#mustang').disabled=false;$('#paul').disabled=false;distanceResult()};
 $('#dist-distPlayers').onchange=e=>{distPlayers=+e.target.value;target=null;mustang=false;paul=false;distance()};
 $('#weapon').onchange=e=>{calcWeapon=e.target.value;weapon=calcWeapons.find(w=>w[0]===calcWeapon)[2];distanceResult()};
 ['scope','rose','mustang','paul'].forEach(id=>$('#'+id).onchange=()=>{scope=$('#scope').checked;rose=$('#rose').checked;mustang=$('#mustang').checked;paul=$('#paul').checked;distanceResult()});
 distanceResult();
}
function distanceResult(){
 $('#target-hint').textContent=target===null?'위 그림에서 자리를 골라주세요.':'상대에게 실제로 있는 것만 체크하세요.';
 const result=$('#dist-result');
 if(target===null){result.className='calc-answer';result.innerHTML='<strong>누구에게 쏘려 하나요?</strong><p>자리를 누르면 결과가 나와요.</p>';return}
 const base=Math.min(target,distPlayers-target),dist=Math.max(1,base+Number(mustang)+Number(paul)-Number(scope)-Number(rose)),reach=calcWeapons.find(w=>w[0]===calcWeapon)[2],hit=dist<=reach;
 result.className='calc-answer '+(hit?'can-shoot':'cannot-shoot');
 result.innerHTML=`<strong>상대(${target}번)에게 ${hit?'총이 닿아요':'총이 닿지 않아요'}</strong><div class="calc-comparison"><span>거리<b>${dist}</b></span><i>${hit?'≤':'>'}</i><span>내 무기 사거리<b>${reach}</b></span></div><p>거리 ${base}${mustang?' + 야생마 1':''}${paul?' + 폴 리그레트 1':''}${scope?' − 내 조준경 1':''}${rose?' − 내 로즈 1':''} = ${dist}${base+Number(mustang)+Number(paul)-Number(scope)-Number(rose)<1?' (최소 거리 1)':''}</p><p class="calc-next">${hit?'거리 조건을 충족해요. 내 차례에 사용할 뱅!이 있는지 확인하세요.':'더 가까운 자리를 고르거나, 내 차례에 사거리가 긴 무기를 내 앞 판에 장착하세요.'}</p>`;
}
function search(){openModal(`<h2 style="margin:15px 0">무엇이 궁금한가요?</h2><label class="library-note" for="global-search">카드 이름, 캐릭터, 상황을 입력하세요.</label><input class="search-field" id="global-search" placeholder="예: 공격, 맥주, 감옥, 거리…"><div id="search-results" class="search-results"></div>`);const results=()=>{const q=$('#global-search').value;const hs=[['attack','공격받았어요','뱅 빗나감 기관총 대응'],['distance','거리가 헷갈려요','거리 사거리 무기'],['dying','생명이 0이 됐어요','생명 탈락 회복 맥주'],['start','감옥·폭탄 판정','감옥 다이너마이트 판정'],['win','승리 조건과 탈락 보상','보상 벌칙 부관 무법자 배신자']].filter(h=>normalize(h.join(' ')).includes(normalize(q)));const cs=q?cards.filter(c=>matches(c,q)):cards.filter(c=>['bang','mancato','birra'].includes(c.id));$('#search-results').innerHTML=hs.map(h=>`<button class="search-result" data-help="${h[0]}"><span><b>${h[1]}</b><small>상황별 바로 보기</small></span>→</button>`).join('')+cs.map(c=>`<button class="search-result" data-card="${c.id}">${img(c.id)}<span><b>${c.name}</b><small>${c.short}</small></span>→</button>`).join('')||'<p class="search-empty">결과가 없어요. 다른 단어나 카드 이름으로 찾아보세요.</p>'};$('#global-search').oninput=results;results();$('#global-search').focus()}
function usageGuide(){openModal(`<section class="usage-guide"><h2>플레이 중 사이트는 이렇게 써요</h2><div class="usage-item"><h3>카드 뜻이 궁금하면</h3><p>하단 ‘카드’에서 같은 그림을 찾아 누르세요. 상단 돋보기로 이름·효과를 검색해도 돼요.</p><div class="actions"><button class="btn secondary" data-guide-cards>카드 찾기 →</button><button class="btn text" data-guide-search>검색하기 →</button></div></div><div class="usage-item"><h3>공격받았거나 상황이 궁금하면</h3><p>아래에서 현재 상황을 고르세요. 시작 화면의 ‘막혔을 때’에서도 열 수 있어요.</p>${helps()}</div><div class="usage-item"><h3>다음에 무엇을 할지 모르겠다면</h3><p>하단 ‘진행’에서 2장 뽑기 → 카드 쓰기 → 초과 카드 버리기 순서로 따라가세요. 카드별 규칙은 ‘카드’에서 확인할 수 있어요.</p><button class="btn secondary" data-guide-turn>내 차례 보기 →</button></div></section>`)}
document.querySelector('.usage-fab').onclick=usageGuide;
setTimeout(()=>document.querySelector('.usage-fab').classList.add('compact'),4000);
document.addEventListener('click',e=>{if(e.target.closest('[data-guide-search]')){search();return}if(e.target.closest('[data-guide-cards]')){filter='전체';query='';modal.close();if(location.hash==='#cards')library();else location.hash='cards'}if(e.target.closest('[data-guide-turn]')){modal.close();if(location.hash==='#turn')turn();else location.hash='turn'}});
$('.search-open').onclick=search;document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();search()}});
document.addEventListener('click',e=>{const card=e.target.closest('[data-card]'),help=e.target.closest('[data-help]'),cat=e.target.closest('[data-category]');if(card)cardDetail(card.dataset.card);if(help)showHelp(help.dataset.help);if(cat){filter=cat.dataset.category;query=''}});
function route(){if(modal.open)modal.close();const page=location.hash.slice(1)||'home';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});main.classList.toggle("hand-helper-page",page==="hand");({setup,turn,cards:library,home,hand:()=>{if(typeof hhOpen==="function")hhOpen()}}[page]||home)();window.scrollTo({top:0,behavior:'instant'});document.title=({home:'오늘, 첫 판',setup:'게임 준비',turn:'내 차례',cards:'카드 찾기',hand:'내 카드 활용'}[page]||'오늘, 첫 판')+' — BANG!'}
window.addEventListener('hashchange',route);route();






